SELECT i.IsCreditNote,sign(l.ExtendedPrice) AmountSign,COUNT(*) Lines,SUM(CAST(l.Quantity AS DECIMAL(38,2))*l.UnitPrice) ExTaxAmount,SUM(l.TaxAmount) TaxAmount,SUM(l.ExtendedPrice) ExtendedAmount,SUM(l.LineProfit) RecordedLineProfit,SUM(l.ExtendedPrice-(l.Quantity*l.UnitPrice+l.TaxAmount)) ReconciliationDifference,COUNT(*) FILTER(WHERE l.ExtendedPrice<>(l.Quantity*l.UnitPrice+l.TaxAmount)) Exceptions,COUNT(*) FILTER(WHERE l.TaxAmount<>ROUND(l.Quantity*l.UnitPrice*l.TaxRate*CAST(0.01 AS DECIMAL(3,2)),2)) TaxRoundingExceptions FROM raw.Sales_Invoices i JOIN raw.Sales_InvoiceLines l USING(InvoiceID) GROUP BY 1,2 ORDER BY 1,2